package engine

object Engine {                       // the enclosing scope is the attorney
  final class Grid private[Engine] (private var dirty: Int) {
    private[Engine] def recalc(i: Int): Unit = dirty = i
  }
  object helper {                     // inside the grant scope
    def refresh(g: Grid): Unit = g.recalc(0)
  }
}
